INSERT INTO records.document_summary (id, document_id, patient_person_id, summary_title, summary_enc, enc_key_id, model_name, model_version, is_simulated, reviewed_by_user_id, reviewed_at, created_at) VALUES
  ('cfd00000-0102-4000-8000-000000000001', 'cfd00000-0101-4000-8000-000000000001', 'cfd00000-0001-4000-8000-000000000001', 'Cholesterol slightly high', convert_to('LDL 142 mg/dL is above the 100 target. HDL (48) is acceptable and triglycerides (160) are slightly above normal. Your doctor may continue Atorvastatin and suggest diet changes.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-10-17 14:30:00+05:30', '2026-10-17 11:05:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000002', 'cfd00000-0101-4000-8000-000000000002', 'cfd00000-0001-4000-8000-000000000001', 'No urgent findings', convert_to('Mild hazy area in the right lower zone, likely from last month''s chest infection. Repeat X-ray in 2 weeks.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-10-15 12:00:00+05:30', '2026-10-15 09:40:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000003', 'cfd00000-0101-4000-8000-000000000003', 'cfd00000-0001-4000-8000-000000000001', '3 medicines, 30 days', convert_to('Metformin 500 mg twice daily, Atorvastatin 10 mg after lunch, Vitamin D3 60,000 IU once a week (Sunday). Valid till 14 Nov 2026.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-10-17 10:10:00+05:30', '2026-10-17 10:05:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000004', 'cfd00000-0101-4000-8000-000000000004', 'cfd00000-0001-4000-8000-000000000001', 'Sugar control improving', convert_to('HbA1c 7.4%, down from 7.9% in June. Target is under 7%.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-10-05 10:00:00+05:30', '2026-10-04 16:30:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000005', 'cfd00000-0101-4000-8000-000000000005', 'cfd00000-0001-4000-8000-000000000001', '3-day stay for chest infection', convert_to('Admitted with fever and cough, treated with antibiotics (non-penicillin). Discharged stable.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-09-26 11:30:00+05:30', '2026-09-22 15:00:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000006', 'cfd00000-0101-4000-8000-000000000006', 'cfd00000-0001-4000-8000-000000000001', 'Infection markers raised', convert_to('White cells 13,200, consistent with an infection at the time. Repeat was normal.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-09-26 11:30:00+05:30', '2026-09-20 11:20:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000007', 'cfd00000-0101-4000-8000-000000000007', 'cfd00000-0001-4000-8000-000000000001', 'Normal study', convert_to('Liver, gallbladder and kidneys look normal.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, 'cfd00000-0002-4000-8000-000000000002', '2026-06-12 10:00:00+05:30', '2026-06-11 12:00:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000008', 'cfd00000-0101-4000-8000-000000000008', 'cfd00000-0001-4000-8000-000000000001', 'Mild short sight', convert_to('Glasses -0.75 both eyes. No diabetic eye changes noted.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, NULL, NULL, '2026-05-08 10:00:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000009', 'cfd00000-0101-4000-8000-000000000009', 'cfd00000-0001-4000-8000-000000000001', 'Childhood vaccines listed', convert_to('Photo of a 1990s card: BCG, DPT, polio and measles. A doctor can confirm it.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, NULL, NULL, '2026-10-17 13:40:00+05:30'),
  ('cfd00000-0102-4000-8000-000000000010', 'cfd00000-0101-4000-8000-000000000010', 'cfd00000-0001-4000-8000-000000000001', 'Health cover card', convert_to('Family floater cover of Rs 5 lakh a year at empanelled hospitals. Card holder: Anjali Menon.', 'UTF8'), 'demo-none', 'carefusion-demo-summariser (simulated AI output)', 'sim-0.1', true, NULL, NULL, '2026-03-02 09:30:00+05:30')
