INSERT INTO ai.chat_message (id, session_id, seq, role, body_enc, enc_key_id, source_refs, red_flag, created_at) VALUES
  ('cfd00000-0121-4000-8000-000000000101', 'cfd00000-0120-4000-8000-000000000001', 1, 'user', convert_to('My lipid report came today. Is my cholesterol bad?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-10-17 15:40:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000102', 'cfd00000-0120-4000-8000-000000000001', 2, 'assistant', convert_to('Your LDL is 142 mg/dL, a little above the 100 your doctor aims for. HDL (48) and triglycerides (160) are close to normal. Atorvastatin usually takes 6-8 weeks to show its full effect, and your current course began in August. This is simulated guidance, not a diagnosis.', 'UTF8'), 'demo-none', '[{"label": "Lipid profile · 17 Oct", "simulated": true, "document_id": "cfd00000-0101-4000-8000-000000000001"}]'::jsonb, false, '2026-10-17 15:40:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000103', 'cfd00000-0120-4000-8000-000000000001', 3, 'user', convert_to('Should I take a higher dose?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-10-17 15:41:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000104', 'cfd00000-0120-4000-8000-000000000001', 4, 'assistant', convert_to('Only your doctor can change a dose. I can add this question to your next visit on 21 Oct with Dr. Arun Nair, or you can message him now.', 'UTF8'), 'demo-none', '[{"label": "Prescription · e-signed", "simulated": true, "document_id": "cfd00000-0101-4000-8000-000000000003"}]'::jsonb, false, '2026-10-17 15:41:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000201', 'cfd00000-0120-4000-8000-000000000002', 1, 'user', convert_to('My chest X-ray images are in Documents. Can you explain the result in simple words?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-10-15 17:05:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000202', 'cfd00000-0120-4000-8000-000000000002', 2, 'assistant', convert_to('Dr. Arun Nair reviewed your chest X-ray (PA view, 15 Oct). It shows a mild hazy area in the lower right part of the lung, which doctors often see after a recent chest infection. No urgent findings were noted. This is simulated guidance, not a diagnosis.', 'UTF8'), 'demo-none', '[{"label": "Chest X-ray, PA view · 15 Oct", "simulated": true, "document_id": "cfd00000-0101-4000-8000-000000000002"}]'::jsonb, false, '2026-10-15 17:05:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000203', 'cfd00000-0120-4000-8000-000000000002', 3, 'user', convert_to('Is the hazy area serious?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-10-15 17:07:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000204', 'cfd00000-0120-4000-8000-000000000002', 4, 'assistant', convert_to('Your doctor wrote that the changes are mild and likely from last month''s infection, and asked for a repeat X-ray in 2 weeks. I cannot say more than your doctor''s note. If you get fever, chest pain or trouble breathing, call your doctor or 108.', 'UTF8'), 'demo-none', '[{"label": "Doctor''s review note", "simulated": true, "document_id": "cfd00000-0101-4000-8000-000000000002"}]'::jsonb, false, '2026-10-15 17:07:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000205', 'cfd00000-0120-4000-8000-000000000002', 5, 'user', convert_to('When should I repeat it?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-10-15 17:10:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000206', 'cfd00000-0120-4000-8000-000000000002', 6, 'assistant', convert_to('Your record shows a repeat chest X-ray on 29 Oct at Radiology, Demo General Hospital (any time 9 to 4).', 'UTF8'), 'demo-none', '[{"label": "Dates · 29 Oct", "simulated": true}]'::jsonb, false, '2026-10-15 17:10:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000301', 'cfd00000-0120-4000-8000-000000000003', 1, 'user', convert_to('Can I fast during Onam with Metformin?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-09-02 19:30:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000302', 'cfd00000-0120-4000-8000-000000000003', 2, 'assistant', convert_to('Fasting while taking diabetes medicines can drop your sugar too low. Please do not stop or skip Metformin on your own. A full-day fast is not advised without your doctor''s plan. Simulated guidance only.', 'UTF8'), 'demo-none', '[{"label": "Metformin · prescription", "simulated": true}]'::jsonb, false, '2026-09-02 19:30:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000303', 'cfd00000-0120-4000-8000-000000000003', 3, 'user', convert_to('What if I only skip lunch?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-09-02 19:33:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000304', 'cfd00000-0120-4000-8000-000000000003', 4, 'assistant', convert_to('Skipping a meal while on Metformin carries a lower risk than with some other sugar-lowering medicines, but low sugar can still happen. It is best to ask your doctor before changing meal times.', 'UTF8'), 'demo-none', '[{"label": "Your record · medicines", "simulated": true}]'::jsonb, false, '2026-09-02 19:33:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000305', 'cfd00000-0120-4000-8000-000000000003', 5, 'user', convert_to('What are the signs of low sugar?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-09-02 19:36:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000306', 'cfd00000-0120-4000-8000-000000000003', 6, 'assistant', convert_to('Shakiness, sweating, hunger, headache, confusion or a fast heartbeat. Take something sugary and check your sugar. If you faint or feel very unwell, call 108.', 'UTF8'), 'demo-none', '[{"label": "General guidance", "simulated": true}]'::jsonb, false, '2026-09-02 19:36:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000307', 'cfd00000-0120-4000-8000-000000000003', 7, 'user', convert_to('Can you tell the doctor?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-09-02 19:40:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000308', 'cfd00000-0120-4000-8000-000000000003', 8, 'assistant', convert_to('I can add this question to your next visit with Dr. Arun Nair, or you can message him. Only your doctor can change your plan.', 'UTF8'), 'demo-none', '[{"label": "Shared with your doctor: not sent", "simulated": true}]'::jsonb, false, '2026-09-02 19:40:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000309', 'cfd00000-0120-4000-8000-000000000003', 9, 'user', convert_to('Okay, I will message him.', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-09-02 19:48:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000401', 'cfd00000-0120-4000-8000-000000000004', 1, 'user', convert_to('What are the warning signs of dengue?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-08-12 08:10:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000402', 'cfd00000-0120-4000-8000-000000000004', 2, 'assistant', convert_to('Warning signs include severe belly pain, repeated vomiting, bleeding from gums or nose, black stools, extreme tiredness or restlessness and fast breathing. If you see any of these, go to a hospital the same day or call 108. Simulated guidance, not a diagnosis.', 'UTF8'), 'demo-none', '[{"label": "Health department advisory", "simulated": true}]'::jsonb, false, '2026-08-12 08:10:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000403', 'cfd00000-0120-4000-8000-000000000004', 3, 'user', convert_to('Is mosquito spray enough?', 'UTF8'), 'demo-none', '[]'::jsonb, false, '2026-08-12 08:14:00+05:30'),
  ('cfd00000-0121-4000-8000-000000000404', 'cfd00000-0120-4000-8000-000000000004', 4, 'assistant', convert_to('Spray helps, but removing standing water near your home matters most. Use nets or repellent and keep water containers covered.', 'UTF8'), 'demo-none', '[{"label": "Health department advisory", "simulated": true}]'::jsonb, false, '2026-08-12 08:14:00+05:30')
