INSERT INTO engage.chat_message (id, thread_id, sender_user_id, body_enc, enc_key_id, sent_at) VALUES
  ('cfd00000-0132-4000-8000-000000000101', 'cfd00000-0130-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000001', convert_to('Doctor, my evening BP was 134/86 yesterday. I had missed the dose. Should I worry?', 'UTF8'), 'demo-none', '2026-10-17 09:12:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000102', 'cfd00000-0130-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000002', convert_to('One higher reading after a missed dose is expected. Keep logging morning and evening for a week and share the log with me.', 'UTF8'), 'demo-none', '2026-10-17 11:40:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000103', 'cfd00000-0130-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000002', convert_to('I have also sent your updated prescription. The Atorvastatin dose stays the same for now.', 'UTF8'), 'demo-none', '2026-10-17 14:30:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000104', 'cfd00000-0130-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000002', convert_to('Please do the HbA1c test before your follow-up on 21 Oct.', 'UTF8'), 'demo-none', '2026-10-17 14:30:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000201', 'cfd00000-0130-4000-8000-000000000002', 'cfd00000-0002-4000-8000-000000000008', convert_to('Your follow-up with Dr. Arun Nair is confirmed for Wed 21 Oct, 10:30, OP block 2. Token 16.', 'UTF8'), 'demo-none', '2026-10-14 10:05:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000202', 'cfd00000-0130-4000-8000-000000000002', 'cfd00000-0002-4000-8000-000000000001', convert_to('Thank you. Is parking available?', 'UTF8'), 'demo-none', '2026-10-14 10:20:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000203', 'cfd00000-0130-4000-8000-000000000002', 'cfd00000-0002-4000-8000-000000000008', convert_to('Yes, visitor parking near Gate 3 is free for the first 2 hours.', 'UTF8'), 'demo-none', '2026-10-14 11:02:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000301', 'cfd00000-0130-4000-8000-000000000003', 'cfd00000-0002-4000-8000-000000000004', convert_to('Your lipid profile is ready and added to your Documents.', 'UTF8'), 'demo-none', '2026-10-17 11:05:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000302', 'cfd00000-0130-4000-8000-000000000003', 'cfd00000-0002-4000-8000-000000000001', convert_to('Got it, thank you.', 'UTF8'), 'demo-none', '2026-10-17 11:20:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000401', 'cfd00000-0130-4000-8000-000000000004', 'cfd00000-0002-4000-8000-000000000005', convert_to('Your chest X-ray images are uploaded. Dr. Arun Nair will review and message you.', 'UTF8'), 'demo-none', '2026-10-15 09:40:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000501', 'cfd00000-0130-4000-8000-000000000005', 'cfd00000-0002-4000-8000-000000000101', convert_to('Your retina check is normal. Repeat the eye check once a year because of diabetes.', 'UTF8'), 'demo-none', '2026-10-02 12:30:00+05:30'),
  ('cfd00000-0132-4000-8000-000000000601', 'cfd00000-0130-4000-8000-000000000006', 'cfd00000-0002-4000-8000-000000000009', convert_to('Free diabetes screening camp at PHC Konni on 25 Oct, 9:00-13:00. Bring your ABHA card.', 'UTF8'), 'demo-none', '2026-09-28 10:00:00+05:30')
