INSERT INTO engage.rating (id, rater_person_id, target_type, target_id, stars, comment, moderation_status, department_id, tags, created_at) VALUES
  ('cfd00000-0160-4000-8000-000000000001', 'cfd00000-0190-4000-8000-000000000001', 'hospital', 'cfd00000-0010-4000-8000-000000000001', 5, 'Dr. Arun Nair explained my sugar report slowly and in Malayalam. The token system meant I waited only 20 minutes.', 'published', 'cfd00000-0011-4000-8000-000000000101', ARRAY['explains clearly', 'short wait']::text[], '2026-10-12 18:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000002', 'cfd00000-0190-4000-8000-000000000002', 'hospital', 'cfd00000-0010-4000-8000-000000000001', 4, 'Medicines were ready when the app said. One brand was out of stock, but they gave an approved substitute.', 'published', NULL, ARRAY['Pharmacy', 'medicines ready']::text[], '2026-10-10 17:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000003', 'cfd00000-0001-4000-8000-000000001120', 'hospital', 'cfd00000-0010-4000-8000-000000000003', 5, 'Dr. Lakshmi Varma checked my feet and eyes in one visit. Clean ward, helpful nurses.', 'published', 'cfd00000-0011-4000-8000-000000000305', ARRAY['clean ward', 'kind staff']::text[], '2026-10-08 12:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000004', 'cfd00000-0190-4000-8000-000000000003', 'hospital', 'cfd00000-0010-4000-8000-000000000001', 3, 'Results came on the app the same afternoon, but the sample queue was long at 8 am.', 'published', 'cfd00000-0011-4000-8000-000000000108', ARRAY['fast results', 'long queue']::text[], '2026-10-06 13:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000005', 'cfd00000-0190-4000-8000-000000000004', 'hospital', 'cfd00000-0010-4000-8000-000000000010', 5, 'Walk-in dengue test with no waiting. The ASHA worker helped my mother register on the app.', 'published', 'cfd00000-0011-4000-8000-000000001001', ARRAY['no waiting', 'helpful staff']::text[], '2026-10-02 11:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000006', 'cfd00000-0001-4000-8000-000000001002', 'hospital', 'cfd00000-0010-4000-8000-000000000002', 2, 'Good doctor, but the X-ray machine was down and I had to come back the next day.', 'published', NULL, ARRAY['equipment down', 'Orthopaedics']::text[], '2026-09-29 19:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000007', 'cfd00000-0190-4000-8000-000000000005', 'hospital', 'cfd00000-0010-4000-8000-000000000001', 4, 'Chest X-ray done quickly. The report was easy to read with the AI summary marked clearly as not final.', 'published', 'cfd00000-0011-4000-8000-000000000109', ARRAY['quick', 'clear report']::text[], '2026-09-25 15:00:00+05:30'),
  ('cfd00000-0160-4000-8000-000000000008', 'cfd00000-0190-4000-8000-000000000006', 'hospital', 'cfd00000-0010-4000-8000-000000000003', 5, 'Diya''s vaccine was on time and the nurse explained side effects. Reminder came the day before.', 'published', 'cfd00000-0011-4000-8000-000000000303', ARRAY['on time', 'explained side effects']::text[], '2026-09-20 10:00:00+05:30')
